{
  "findings": [
    {
      "check_id": "CKV_AWS_144",
      "title": "Transit Gateway does not have DNS support enabled",
      "resource": "aws_ec2_transit_gateway.pass2",
      "severity": "MEDIUM",
      "explanation": "DNS support is not enabled for the transit gateway. Without DNS support, resources connected to the transit gateway may not be able to resolve domain names, which can lead to connectivity issues."
    }
  ],
  "patched_code": "resource \"aws_ec2_transit_gateway\" \"pass2\" {\n  description = \"sato\"\n  auto_accept_shared_attachments = \"disable\"\n  dns_support = \"enable\"\n}\n",
  "fix_summary": "Enabled DNS support for the transit gateway to ensure proper domain name resolution for connected resources."
}
